import React, { useState, useEffect, useRef } from 'react';
import './AgentsView.css';

const AGENTS = [
  {
    id: 'data-quality',
    name: 'Data Quality Agent',
    shortLabel: 'Data Quality',
    color: '#334155',
    description: 'Validates and normalizes patient records, consent flags, and refill timing. Ensures data is consistent and ready for risk scoring and downstream agents.',
  },
  {
    id: 'prediction',
    name: 'Prediction Agent',
    shortLabel: 'Prediction',
    color: '#D97706',
    description: 'Computes adherence risk scores and assigns High, Medium, or Low labels. Produces confidence signals used by the notification and escalation agents.',
  },
  {
    id: 'notification',
    name: 'Notification Agent',
    shortLabel: 'Notification',
    color: '#16A34A',
    description: 'Orchestrates consent checks, throttling, and multi-channel messaging. Sends SMS, Email, and Push notifications to patients based on risk and preferences.',
  },
  {
    id: 'escalation',
    name: 'Escalation Agent',
    shortLabel: 'Escalation',
    color: '#9333EA',
    description: 'Triggers clinician escalation from risk thresholds and refill status. Ensures high-risk or overdue patients are flagged for care team follow-up.',
  },
  {
    id: 'compliance',
    name: 'Compliance Agent',
    shortLabel: 'Compliance',
    color: '#0ea5e9',
    description: 'Maintains audit trail, notification status, and governance logs. Supports reporting and regulatory requirements for adherence interventions.',
  },
];

function getTaskCountForAgent(agentId, index, kpis) {
  const interventions30d = kpis?.interventions_30d ?? kpis?.notified_unique ?? 0;
  const notifiedToday = kpis?.notified_today ?? 0;
  if (index === 0) return Math.min(interventions30d + 20, 999);
  if (index === 1) return Math.min(interventions30d + 5, 999);
  if (index === 2) return notifiedToday || Math.max(0, Math.floor(interventions30d / 30));
  if (index === 3) return Math.max(0, Math.floor(interventions30d * 0.15));
  return interventions30d;
}

const AGENT_METRIC_LABELS = [
  'Records processed',
  'Risk assessments',
  'Notifications sent',
  'Escalations',
  'Events logged',
];

function getConfidenceForAgent(index) {
  const base = [98, 94, 91, 89, 97];
  return base[index] ?? 92;
}

function AgentsView({ dashboardData, systemStatus }) {
  const kpis = dashboardData?.kpis ?? {};
  const agentsRunning = systemStatus?.agents_running ?? 0;
  const liveOn = systemStatus?.live_on ?? false;
  const isPipelineActive = liveOn && agentsRunning > 0;

  /* Confidence count-up on load: 0 → target over ~2.2s */
  const CONFIDENCE_ANIM_DURATION_MS = 2200;
  const [confidenceProgress, setConfidenceProgress] = useState(0);
  const rafRef = useRef(null);
  const startRef = useRef(null);

  useEffect(() => {
    setConfidenceProgress(0);
    startRef.current = null;
    const tick = (timestamp) => {
      if (startRef.current == null) startRef.current = timestamp;
      const elapsed = timestamp - startRef.current;
      const linear = Math.min(1, elapsed / CONFIDENCE_ANIM_DURATION_MS);
      const progress = 1 - Math.pow(1 - linear, 1.4);
      setConfidenceProgress(progress);
      if (linear < 1) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  return (
    <div className="agents-view">
      <div className="agents-view-inner">
        <p className="agents-view-intro">
          AI agents that power the medication adherence pipeline. Each agent runs in sequence to validate data, predict risk, send notifications, escalate when needed, and log compliance. The counts below are estimated from your dashboard data (e.g. interventions, notifications sent).
        </p>
        <div className="agents-view-grid" role="list">
          {AGENTS.map((agent, index) => {
            const tasksCompleted = getTaskCountForAgent(agent.id, index, kpis);
            const targetConfidence = getConfidenceForAgent(index);
            const confidence = Math.round(confidenceProgress * targetConfidence);
            const active = isPipelineActive;
            return (
              <article
                key={agent.id}
                className={`agents-view-card ${active ? 'agents-view-card--active' : ''}`}
                style={{
                  '--agent-color': agent.color,
                  '--animation-order': index,
                }}
                role="listitem"
              >
                <div className="agents-view-card-glow" aria-hidden />
                <div className="agents-view-card-accent" aria-hidden />
                {active && <span className="agents-view-card-pulse" aria-hidden />}

                <div className="agents-view-card-header">
                  <span className="agents-view-card-number">{index + 1}</span>
                  <h3 className="agents-view-card-title">{agent.name}</h3>
                  <span className={`agents-view-card-status agents-view-card-status--${active ? 'active' : 'ready'}`}>
                    {active ? 'Active' : 'Ready'}
                  </span>
                </div>

                <p className="agents-view-card-desc">{agent.description}</p>

                <div className="agents-view-card-metrics">
                  <div className="agents-view-metric">
                    <span className="agents-view-metric-value agents-view-metric-tasks">{tasksCompleted}</span>
                    <span className="agents-view-metric-label" title="Estimated from dashboard (interventions, notifications).">{AGENT_METRIC_LABELS[index]}</span>
                  </div>
                  <div className="agents-view-metric agents-view-metric-confidence-wrap">
                    <div className="agents-view-confidence-ring" style={{ '--confidence': confidence }}>
                      <span className="agents-view-confidence-value">{confidence}%</span>
                    </div>
                    <span className="agents-view-metric-label">Confidence</span>
                  </div>
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export default AgentsView;
