import React, { useState, useEffect, useRef } from 'react';
import './Charts.css';

const DEFAULT_KPIS = {
  low_count: 0,
  med_count: 0,
  high_count: 0,
  interventions_30d: 0,
  interventions_7d: 0,
  notified_unique: 0,
  responded_unique: 0,
  notified_today: 0,
};

// Full donut: Low (red), Medium (amber), High (green) — distinct colors by adherence
const DONUT_COLORS = {
  low: { main: '#EF4444', light: '#F87171', dark: '#DC2626' },
  medium: { main: '#F59E0B', light: '#FBBF24', dark: '#D97706' },
  high: { main: '#22C55E', light: '#4ADE80', dark: '#16a34a' },
};

// Full 360° ring: start at top (-90°), sweep entire circle
const RING_START_ANGLE = -90;
const RING_SWEEP = 360;

// 3D gradient: lighter top, darker bottom for subtle bevel
function DonutSegment({ cx, cy, R, r, startAngle, endAngle, fill, id, label, value, onHover, useSolidFill }) {
  const toRad = (deg) => (deg * Math.PI) / 180;
  const start = toRad(startAngle);
  const end = toRad(endAngle);
  const x1 = cx + R * Math.cos(start);
  const y1 = cy + R * Math.sin(start);
  const x2 = cx + R * Math.cos(end);
  const y2 = cy + R * Math.sin(end);
  const x3 = cx + r * Math.cos(end);
  const y3 = cy + r * Math.sin(end);
  const x4 = cx + r * Math.cos(start);
  const y4 = cy + r * Math.sin(start);
  const large = endAngle - startAngle > 180 ? 1 : 0;
  const d = [
    `M ${x1} ${y1}`,
    `A ${R} ${R} 0 ${large} 1 ${x2} ${y2}`,
    `L ${x3} ${y3}`,
    `A ${r} ${r} 0 ${large} 0 ${x4} ${y4}`,
    'Z',
  ].join(' ');
  return (
    <path
      d={d}
      fill={useSolidFill ? fill : `url(#donut-grad-${id})`}
      className="donut-segment"
      data-segment={label}
      onMouseEnter={() => onHover && onHover(label, value)}
      onMouseLeave={() => onHover && onHover(null, null)}
    />
  );
}

const SEGMENT_LABELS = ['Low', 'Medium', 'High'];

function AdherenceDonut({ kpis }) {
  const [hoveredSegment, setHoveredSegment] = useState(null);
  const [hoveredValue, setHoveredValue] = useState(null);
  const [fillProgress, setFillProgress] = useState(0);
  const rafRef = useRef(null);
  const startRef = useRef(null);

  const low = kpis.low_count || 0;
  const med = kpis.med_count || 0;
  const high = kpis.high_count || 0;
  const total = low + med + high;
  const size = 200;
  const cx = size / 2;
  const cy = size / 2;
  const R = size * 0.4;
  const r = size * 0.22;

  // Ring fill animation on load: 0 → 1 over 2s
  useEffect(() => {
    startRef.current = null;
    const DURATION_MS = 2000;
    const tick = (timestamp) => {
      if (startRef.current == null) startRef.current = timestamp;
      const elapsed = timestamp - startRef.current;
      const linear = Math.min(1, elapsed / DURATION_MS);
      const progress = 1 - Math.pow(1 - linear, 1.4);
      setFillProgress(progress);
      if (linear < 1) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => { if (rafRef.current != null) cancelAnimationFrame(rafRef.current); };
  }, []);

  const start = RING_START_ANGLE;
  let a0 = start;
  const segmentData = [
    [low, DONUT_COLORS.low, 'Low'],
    [med, DONUT_COLORS.medium, 'Medium'],
    [high, DONUT_COLORS.high, 'High'],
  ];
  const segments = [];
  if (total > 0) {
    segmentData.forEach(([value, colors], i) => {
      const angle = (value / total) * RING_SWEEP;
      if (angle > 0) {
        segments.push({
          startAngle: a0,
          endAngle: a0 + angle,
          fill: colors.main,
          light: colors.light,
          dark: colors.dark,
          id: i,
          label: SEGMENT_LABELS[i],
          value,
        });
        a0 += angle;
      }
    });
  }
  const singleSegment = segments.length === 1;
  if (total === 0) {
    segments.push({
      startAngle: start,
      endAngle: start + RING_SWEEP,
      fill: '#94a3b8',
      light: '#94a3b8',
      dark: '#64748b',
      id: 0,
      label: '—',
      value: 0,
    });
  }

  const handleSegmentHover = (label, value) => {
    setHoveredSegment(label);
    setHoveredValue(value);
  };

  return (
    <div className="donut-chart-inner">
      <div className="donut-3d-wrap">
        <div className="donut-visual">
          <svg className="donut-svg" viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
            <defs>
              <radialGradient id="donut-hole-depth" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor="rgba(100,116,139,0.25)" />
                <stop offset="70%" stopColor="rgba(148,163,184,0.12)" />
                <stop offset="100%" stopColor="rgba(148,163,184,0)" />
              </radialGradient>
              {segments.map((seg, i) => (
                <linearGradient key={`grad-${i}`} id={`donut-grad-${seg.id}`} x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor={seg.light ?? seg.fill} stopOpacity="1" />
                  <stop offset="12%" stopColor={seg.light ?? seg.fill} stopOpacity="1" />
                  <stop offset="25%" stopColor={seg.fill} stopOpacity="1" />
                  <stop offset="55%" stopColor={seg.fill} stopOpacity="1" />
                  <stop offset="100%" stopColor={seg.dark} stopOpacity="1" />
                </linearGradient>
              ))}
            </defs>
            <circle cx={cx} cy={cy} r={r} fill="url(#donut-hole-depth)" />
            <circle cx={cx} cy={cy} r={R} fill="none" stroke="rgba(100,116,139,0.2)" strokeWidth="1" className="donut-rim" />
            <circle cx={cx} cy={cy} r={r} fill="none" stroke="rgba(255,255,255,0.4)" strokeWidth="0.8" className="donut-inner-rim" />
            {segments.map((seg, i) => {
              const span = seg.endAngle - seg.startAngle;
              const progressSpan = span * fillProgress;
              const endAngle = seg.startAngle + progressSpan;
              return (
                <DonutSegment
                  key={i}
                  cx={cx}
                  cy={cy}
                  R={R}
                  r={r}
                  startAngle={seg.startAngle}
                  endAngle={endAngle}
                  fill={seg.fill}
                  id={seg.id}
                  label={seg.label}
                  value={seg.value}
                  onHover={handleSegmentHover}
                  useSolidFill={singleSegment}
                />
              );
            })}
          </svg>
        </div>
        {hoveredSegment != null && (
          <div className="donut-hover-tooltip">
            <span className="donut-hover-label">{hoveredSegment}</span>
            <span className="donut-hover-count">{hoveredValue != null ? hoveredValue.toLocaleString() : '—'}</span>
          </div>
        )}
      </div>
      <div className="donut-legend">
        <div className="donut-legend-item">
          <span className="donut-legend-color" style={{ background: DONUT_COLORS.low.main }} />
          <span className="donut-legend-label">Low</span>
          <span className="donut-legend-value">{low.toLocaleString()}</span>
        </div>
        <div className="donut-legend-item">
          <span className="donut-legend-color" style={{ background: DONUT_COLORS.medium.main }} />
          <span className="donut-legend-label">Medium</span>
          <span className="donut-legend-value">{med.toLocaleString()}</span>
        </div>
        <div className="donut-legend-item">
          <span className="donut-legend-color" style={{ background: DONUT_COLORS.high.main }} />
          <span className="donut-legend-label">High</span>
          <span className="donut-legend-value">{high.toLocaleString()}</span>
        </div>
      </div>
    </div>
  );
}

const BAR_COLORS = ['#00E5FF', '#2ED3B7', '#6366F1', '#22C55E', '#F59E0B'];

// Glossy bar gradient: lighter tint at top (no white), base in middle, darker at bottom
function glossyBarGradient(hex) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  const light = `rgb(${Math.min(255, r + 45)},${Math.min(255, g + 45)},${Math.min(255, b + 45)})`;
  const dark = `rgb(${Math.max(0, r - 35)},${Math.max(0, g - 35)},${Math.max(0, b - 35)})`;
  return `linear-gradient(to bottom, ${light} 0%, ${light} 25%, rgb(${r},${g},${b}) 45%, rgb(${r},${g},${b}) 70%, ${dark} 100%)`;
}

function InterventionBarChart({ kpis }) {
  const interventions30d = kpis.interventions_30d || 0;
  const interventions7d = kpis.interventions_7d || 0;
  const notified = kpis.notified_unique || 0;
  const responded = kpis.responded_unique || 0;
  const today = kpis.notified_today || 0;
  const responseRate = notified > 0 ? ((responded / notified) * 100).toFixed(1) : '0';

  const items = [
    { label: '30 Days', sublabel: 'Total interventions', value: interventions30d },
    { label: '7 Days', sublabel: 'This week', value: interventions7d },
    { label: 'Notified', sublabel: 'Patients sent', value: notified },
    { label: 'Responded', sublabel: `${responseRate}% rate`, value: responded },
    { label: 'Today', sublabel: 'Last 24h', value: today },
  ];
  const maxVal = Math.max(1, ...items.map((i) => i.value));

  return (
    <div className="intervention-metrics-chart intervention-vertical">
      <div className="intervention-metrics-summary">
        <div className="intervention-summary-item">
          <span className="intervention-metrics-total-label">Total (30d)</span>
          <span className="intervention-metrics-total-value">{interventions30d.toLocaleString()}</span>
        </div>
        <div className="intervention-summary-item">
          <span className="intervention-metrics-total-label">Response rate</span>
          <span className="intervention-metrics-total-value">{responseRate}%</span>
        </div>
      </div>
      <div className="intervention-y-axis-label">Count</div>
      <div className="bar-chart-vertical-inner">
        {items.map((item, i) => (
          <div key={item.label} className="bar-chart-vertical-col">
            <span className="bar-chart-vertical-value">{item.value.toLocaleString()}</span>
            <div className="bar-chart-vertical-track">
              <div
                className="bar-chart-vertical-fill bar-chart-vertical-fill-glossy"
                style={{
                  height: `${(item.value / maxVal) * 100}%`,
                  background: glossyBarGradient(BAR_COLORS[i % BAR_COLORS.length]),
                }}
              />
            </div>
            <div className="bar-chart-vertical-labels">
              <span className="bar-chart-vertical-label">{item.label}</span>
              <span className="bar-chart-vertical-sublabel">{item.sublabel}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function Charts({ trendData, data }) {
  const kpis = (data && data.kpis) ? data.kpis : DEFAULT_KPIS;

  return (
    <div className="charts-container">
      <div className="chart-card card chart-3d">
        <div className="chart-header">
          <h3 className="card-title">📊 Adherence Distribution</h3>
          <div className="chart-info-badge">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M12 2L2 7L12 12L22 7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M2 17L12 22L22 17" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M2 12L12 17L22 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <span>Real-time Data</span>
          </div>
        </div>
        <div className="donut-chart" style={{ width: '100%', minHeight: '260px' }}>
          <AdherenceDonut kpis={kpis} />
        </div>
      </div>

      <div className="chart-card card chart-3d">
        <div className="chart-header">
          <h3 className="card-title">📈 Intervention Metrics</h3>
          <div className="chart-info-badge">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M3 3v18h18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M18 7l-5-5-5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M7 21l5-5 5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <span>Performance</span>
          </div>
        </div>
        <div className="bar-chart bar-chart-vertical-wrap" style={{ width: '100%', minHeight: '200px' }}>
          <InterventionBarChart kpis={kpis} />
        </div>
      </div>
    </div>
  );
}

export default Charts;
