import React from 'react';
import './ImportantDetails.css';

/** Format integer for display (e.g. 1234 → "1,234") */
function formatCount(n) {
  if (n == null || Number.isNaN(n)) return '0';
  return Number(n).toLocaleString();
}

function ImportantDetails({ data, onViewChange }) {
  if (!data || !data.kpis) return null;

  const { kpis } = data;
  const alertLevel = kpis.high_risk_now > 50 ? 'high' :
                     kpis.high_risk_now > 20 ? 'medium' : 'low';

  return (
    <div className="important-details-card key-metrics-card">
      <div className="important-details-header">
        <div className="details-title-wrapper">
          <svg className="details-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
            <path d="M12 2L2 7L12 12L22 7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <path d="M2 17L12 22L22 17" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <path d="M2 12L12 17L22 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          <h2 className="important-details-title">Key Metrics</h2>
        </div>
        <div className={`alert-badge alert-${alertLevel}`} role="status">
          {alertLevel === 'high' ? 'Critical' : alertLevel === 'medium' ? 'Attention' : 'Normal'}
        </div>
      </div>

      <div className="important-details-content key-metrics-content">
        <section className="key-metric-extra-section" aria-labelledby="key-metric-routing-label">
          <h3 id="key-metric-routing-label" className="key-metric-section-label">Routed to clinic &amp; other details</h3>
          <ul className="key-metric-details-list" role="list">
            <li>
              <button
                type="button"
                className="key-metric-list-item key-metric-list-item-routed key-metric-list-item-clickable"
                title="View patients routed to clinic (Member ID and reason only)"
                onClick={() => onViewChange && onViewChange('routed-to-clinic')}
              >
                <span className="key-metric-list-accent" aria-hidden />
                <span className="key-metric-list-main">
                  <span className="key-metric-list-label">Routed to clinic</span>
                  <span className="key-metric-list-detail">Escalation candidates — click to view</span>
                </span>
                <span className="key-metric-list-count highlight">{formatCount(kpis.high_risk_refill_over)}</span>
              </button>
            </li>
            <li>
              <button
                type="button"
                className="key-metric-list-item key-metric-list-item-refill key-metric-list-item-clickable"
                title="View patients with refill overdue (Member ID and reason only)"
                onClick={() => onViewChange && onViewChange('refill-overdue')}
              >
                <span className="key-metric-list-accent" aria-hidden />
                <span className="key-metric-list-main">
                  <span className="key-metric-list-label">Refill overdue</span>
                  <span className="key-metric-list-detail">Need refill now — click to view</span>
                </span>
                <span className="key-metric-list-count">{formatCount(kpis.refill_over_due_count)}</span>
              </button>
            </li>
            <li>
              <div
                className="key-metric-list-item key-metric-list-item-appreciation"
                title="Number of patients who received an appreciation notification"
              >
                <span className="key-metric-list-accent" aria-hidden />
                <span className="key-metric-list-main">
                  <span className="key-metric-list-label">Appreciation sent</span>
                  <span className="key-metric-list-detail">Refill improved / thank-you messages sent</span>
                </span>
                <span className="key-metric-list-count">{formatCount(kpis.appreciation_sent_count)}</span>
              </div>
            </li>
          </ul>
        </section>
      </div>
    </div>
  );
}

export default ImportantDetails;
