import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import './PatientListView.css';

const API_BASE = process.env.REACT_APP_API_URL || '/api';

function RefillOverdueView() {
  const [list, setList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchList = useCallback(() => {
    setLoading(true);
    setError(null);
    axios.get(`${API_BASE}/patient-lists?type=refill_overdue`)
      .then((res) => {
        setList(res.data.refill_overdue || []);
        setError(null);
      })
      .catch((err) => {
        const msg = err.response?.status === 404
          ? 'Patient list not available. Ensure the backend is running and the API serves /api/patient-lists.'
          : (err.message || 'Failed to load list');
        setError(msg);
        setList([]);
      })
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { fetchList(); }, [fetchList]);

  if (loading) {
    return (
      <div className="patient-list-view">
        <div className="patient-list-view-inner patient-list-view-loading-state">
          <div className="patient-list-loading-card">
            <div className="patient-list-loading-icon" aria-hidden>
              <span className="patient-list-loading-emoji">✨</span>
            </div>
            <p className="patient-list-loading-title">AI is extracting details</p>
            <p className="patient-list-loading-dots">
              <span className="patient-list-loading-dot">.</span>
              <span className="patient-list-loading-dot">.</span>
              <span className="patient-list-loading-dot">.</span>
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="patient-list-view">
      <div className="patient-list-view-inner">
        {error && (
          <p className="patient-list-view-error">
            {error}
            <button type="button" className="patient-list-view-retry" onClick={fetchList}>Retry</button>
          </p>
        )}
        <p className="patient-list-view-intro">
          Patients with refill overdue. Only Member ID and reason (days overdue) are shown; no other PII.
        </p>
        <div className="patient-list-view-table-wrap">
          <table className="patient-list-view-table" role="grid">
            <thead>
              <tr>
                <th>Member ID</th>
                <th>Reason</th>
                <th>AI Insight</th>
              </tr>
            </thead>
            <tbody>
              {list.length === 0 ? (
                <tr>
                  <td colSpan={3} className="patient-list-view-empty">
                    {error ? 'Could not load list. Fix the connection and click Retry above.' : 'No patients in this list'}
                  </td>
                </tr>
              ) : (
                list.map((item, i) => (
                  <tr key={item.member_id + String(i)}>
                    <td className="patient-list-view-id">{item.member_id}</td>
                    <td>{item.reason || '—'}</td>
                    <td className="patient-list-view-insight">{item.ai_insight || item.reason || '—'}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default RefillOverdueView;
