import React, { useState } from 'react';
import Header from './Header';
import ExecutiveSummary from './ExecutiveSummary';
import KPICards from './KPICards';
import Charts from './Charts';
import DataSnapshot from './DataSnapshot';
import ImportantDetails from './ImportantDetails';
import DashboardCalendar from './DashboardCalendar';
import AgentsView from './AgentsView';
import RoutedToClinicView from './RoutedToClinicView';
import RefillOverdueView from './RefillOverdueView';
import RobotLoader from './RobotLoader';
import './Dashboard.css';

function Dashboard({ dashboardData, systemStatus, trendData, onSystemControl, toastFilter, onToastFilterChange }) {
  const [viewMode, setViewMode] = useState('dashboard');

  if (!dashboardData || !systemStatus) {
    return <RobotLoader />;
  }

  return (
    <div className="dashboard">
      <Header
        systemStatus={systemStatus}
        onSystemControl={onSystemControl}
        toastFilter={toastFilter}
        onToastFilterChange={onToastFilterChange}
        viewMode={viewMode}
        onViewChange={setViewMode}
      />

      {viewMode === 'agents' ? (
        <AgentsView dashboardData={dashboardData} systemStatus={systemStatus} />
      ) : viewMode === 'routed-to-clinic' ? (
        <RoutedToClinicView />
      ) : viewMode === 'refill-overdue' ? (
        <RefillOverdueView />
      ) : (
        <div className="dashboard-content">
        <div className="dashboard-left">
          <ExecutiveSummary data={dashboardData} />
          <KPICards data={dashboardData} />
          <Charts trendData={trendData} data={dashboardData} />
        </div>
        
        <div className="dashboard-right">
          <div className="dashboard-right-spacer-card">
            <DashboardCalendar data={dashboardData} />
          </div>
          <ImportantDetails data={dashboardData} onViewChange={setViewMode} />
        </div>

        <div className="dashboard-snapshot-row">
          <DataSnapshot />
        </div>
      </div>
      )}
    </div>
  );
}

export default Dashboard;
