import React, { useState } from 'react';
import './DashboardCalendar.css';

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAY_ABBREV = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/** Generate a stable one-liner for a given date. Uses real KPIs when date is today and data is available. */
function getDaySummary(dateKey, data) {
  if (!dateKey) return null;
  const [y, m, d] = dateKey.split('-').map(Number);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const selected = new Date(y, m - 1, d);
  selected.setHours(0, 0, 0, 0);
  const isToday = selected.getTime() === today.getTime();
  const isFuture = selected.getTime() > today.getTime();
  const kpis = data?.kpis;

  if (isToday && kpis) {
    const notified = kpis.notified_today ?? 0;
    const appreciated = kpis.appreciation_sent_count ?? 0;
    const stabilized = kpis.stabilized_count ?? 0;
    const highRisk = kpis.high_risk_now ?? 0;
    const parts = [];
    if (notified > 0) parts.push(`Notifications sent: ${notified}`);
    if (appreciated > 0) parts.push(`Patients appreciated: ${appreciated}`);
    if (stabilized > 0) parts.push(`Patients stabilized: ${stabilized}`);
    if (highRisk > 0) parts.push(`High-risk patients: ${highRisk}`);
    if (parts.length === 0) return 'No interventions recorded for today yet.';
    return parts.join(', ') + '.';
  }

  if (isFuture) {
    const futureMessages = [
      'Upcoming date—plan adherence outreach, refill reminders, and follow-ups as needed.',
      'Schedule notifications and patient follow-ups for this day.',
      'Use this day for planned interventions and high-risk patient checks.',
    ];
    const seed = y * 10000 + m * 100 + d;
    const n = (seed * 9301 + 49297) % 233280;
    return futureMessages[n % futureMessages.length];
  }

  // Past date: no data available — generic no-action message
  return 'No action taken for this date.';
}

function DashboardCalendar({ data }) {
  const [viewDate, setViewDate] = useState(() => new Date());
  const today = new Date();
  const [selectedDate, setSelectedDate] = useState({
    year: today.getFullYear(),
    month: today.getMonth(),
    day: today.getDate(),
  });
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startOffset = firstDay.getDay();
  const daysInMonth = lastDay.getDate();
  const isToday = (d) => today.getFullYear() === year && today.getMonth() === month && today.getDate() === d;
  const selectedDateKey = selectedDate
    ? `${selectedDate.year}-${selectedDate.month + 1}-${selectedDate.day}`
    : null;
  const daySummary = getDaySummary(selectedDateKey, data);

  const prevMonth = () => setViewDate((d) => new Date(d.getFullYear(), d.getMonth() - 1));
  const nextMonth = () => setViewDate((d) => new Date(d.getFullYear(), d.getMonth() + 1));

  const goToToday = () => {
    const now = new Date();
    setViewDate(new Date(now.getFullYear(), now.getMonth(), now.getDate()));
    setSelectedDate({
      year: now.getFullYear(),
      month: now.getMonth(),
      day: now.getDate(),
    });
  };

  const isSelectedToday =
    selectedDate &&
    selectedDate.year === today.getFullYear() &&
    selectedDate.month === today.getMonth() &&
    selectedDate.day === today.getDate();

  const handleDayClick = (day) => {
    setSelectedDate({ year, month, day });
  };

  const leadingBlanks = Array.from({ length: startOffset }, (_, i) => (
    <div key={`blank-${i}`} className="dashboard-cal-day dashboard-cal-day-other" aria-hidden="true" />
  ));
  const monthDays = Array.from({ length: daysInMonth }, (_, i) => {
    const day = i + 1;
    const selected =
      selectedDate &&
      selectedDate.year === year &&
      selectedDate.month === month &&
      selectedDate.day === day;
    return (
      <button
        key={day}
        type="button"
        className={`dashboard-cal-day ${isToday(day) ? 'dashboard-cal-day-today' : ''} ${selected ? 'dashboard-cal-day-selected' : ''}`}
        aria-label={isToday(day) ? `Today, ${day}` : `Date ${day}`}
        aria-pressed={selected || isToday(day)}
        onClick={() => handleDayClick(day)}
      >
        {isToday(day) && (
          <svg className="dashboard-cal-today-ring" viewBox="0 0 40 40" fill="none" aria-hidden>
            {/* Hand-drawn style circle: wobbly outline with overlap/curl at top-right */}
            <path
              d="M 20 5
                 C 28.5 4.5 36 10.5 36.5 18.5
                 C 37 26 32.5 34.5 24 36
                 C 15.5 37 7.5 32.5 4 24
                 C 3 16 7 8.5 14.5 5.5
                 C 17 4.5 19 5 20 5
                 Q 23 3.5 21.5 6 Q 20 5 20 5"
              stroke="#e53935"
              strokeWidth="2.25"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
        <span className="dashboard-cal-day-inner">{day}</span>
      </button>
    );
  });
  const totalCells = leadingBlanks.length + monthDays.length;
  const trailingBlanks = totalCells <= 35
    ? Array.from({ length: 35 - totalCells }, (_, i) => (
        <div key={`trail-${i}`} className="dashboard-cal-day dashboard-cal-day-other" aria-hidden="true" />
      ))
    : totalCells <= 42
      ? Array.from({ length: 42 - totalCells }, (_, i) => (
          <div key={`trail-${i}`} className="dashboard-cal-day dashboard-cal-day-other" aria-hidden="true" />
        ))
      : [];

  const selectedLabel = selectedDate
    ? `${MONTH_NAMES[selectedDate.month]} ${selectedDate.day}, ${selectedDate.year}`
    : '';

  return (
    <div className="dashboard-calendar">
      <div className="dashboard-calendar-header">
        <button
          type="button"
          className="dashboard-calendar-nav"
          onClick={prevMonth}
          aria-label="Previous month"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
        <h3 className="dashboard-calendar-title">
          {MONTH_NAMES[month]} {year}
        </h3>
        <button
          type="button"
          className="dashboard-calendar-nav"
          onClick={nextMonth}
          aria-label="Next month"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>
        {!isSelectedToday && (
          <button
            type="button"
            className="dashboard-calendar-today-btn"
            onClick={goToToday}
            aria-label="Go to today"
            title="Go to today"
          >
            Today
          </button>
        )}
      </div>
      <div className="dashboard-calendar-weekdays" role="row">
        {DAY_ABBREV.map((abbrev) => (
          <div key={abbrev} className="dashboard-cal-weekday" role="columnheader">
            {abbrev}
          </div>
        ))}
      </div>
      <div className="dashboard-calendar-grid" role="grid" aria-label={`${MONTH_NAMES[month]} ${year}`}>
        {leadingBlanks}
        {monthDays}
        {trailingBlanks}
      </div>
      <div className="dashboard-calendar-insight">
        <div className="dashboard-calendar-insight-label">
          <span className="dashboard-calendar-insight-icon" aria-hidden>✨</span>
          AI insight — {selectedLabel}
        </div>
        <p className="dashboard-calendar-insight-text">{daySummary}</p>
      </div>
    </div>
  );
}

export default DashboardCalendar;
