import React, { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import './DataSnapshot.css';

const API_BASE = process.env.REACT_APP_API_URL || '/api';
const MEMBER_ID_COLS = ['Member ID', 'Member_ID'];
const PREVIEW_COUNTDOWN_SEC = 10;
/** Columns to hide in Data Snapshot table */
const HIDDEN_COLUMNS = ['patient_display', 'days_until_refill', 'refill_due'];

/** Same format as table cells: exactly what the user sees in the table */
function getDisplayValue(v) {
  if (v === undefined || v === null) return '';
  return String(v);
}

/** Get distinct values for a column – same values as shown in the table, sorted */
function getColumnDistinctValues(rows, col) {
  if (!rows.length) return [];
  const seen = new Set();
  const list = [];
  rows.forEach((row) => {
    const display = getDisplayValue(row[col]);
    if (seen.has(display)) return;
    seen.add(display);
    list.push(display);
  });
  list.sort((a, b) => {
    if (a === '') return 1;
    if (b === '') return -1;
    const na = parseFloat(String(a).replace(/[^0-9.-]/g, ''));
    const nb = parseFloat(String(b).replace(/[^0-9.-]/g, ''));
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
    return String(a).localeCompare(String(b), undefined, { numeric: true });
  });
  return list;
}

/** Dedupe and filter columns for display */
function getDisplayColumns(columns) {
  if (!Array.isArray(columns)) return [];
  const seen = new Set();
  const hidden = new Set(HIDDEN_COLUMNS);
  return columns.filter((col) => {
    const key = String(col).trim();
    if (!key || hidden.has(key) || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
const PREVIEW_COUNTDOWN_OPTIONS = [5, 10, 15, 30];

function DataSnapshot() {
  const [filter, setFilter] = useState('all');
  const [maskPII, setMaskPII] = useState(true);
  const [data, setData] = useState({
    rows: [],
    columns: [],
    counts: { all: 0, low: 0, medium: 0, high: 0 },
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedRowIndex, setSelectedRowIndex] = useState(null);
  const [sendStatus, setSendStatus] = useState(null);
  const [sending, setSending] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewMessage, setPreviewMessage] = useState('');
  const [previewPayload, setPreviewPayload] = useState(null);
  const [previewCountdownSec, setPreviewCountdownSec] = useState(PREVIEW_COUNTDOWN_SEC);
  const [countdown, setCountdown] = useState(PREVIEW_COUNTDOWN_SEC);
  const countdownRef = useRef(null);
  const [piiConfirmOpen, setPiiConfirmOpen] = useState(false);
  const [bulkConfirmOpen, setBulkConfirmOpen] = useState(false);
  const [bulkLevel, setBulkLevel] = useState(null);
  const [bulkMessage, setBulkMessage] = useState('');
  const [bulkSending, setBulkSending] = useState(false);
  const [bulkResult, setBulkResult] = useState(null);
  /** Excel-style: per-column filter. key = column name, value = Set of allowed keys or null (show all) */
  const [columnFilters, setColumnFilters] = useState({});

  const fetchSnapshot = useCallback(async () => {
    setLoading(true);
    setError(null);
    setSendStatus(null);
    try {
      const res = await axios.get(`${API_BASE}/patient-snapshot`, {
        params: { filter, filter_by: 'adherence', mask_pii: maskPII },
      });
      setData({
        rows: res.data.rows || [],
        columns: res.data.columns || [],
        counts: res.data.counts || { all: 0, low: 0, medium: 0, high: 0 },
      });
      setSelectedRowIndex(null);
    } catch (err) {
      setError(err.response?.data?.error || err.message || 'Failed to load snapshot');
      setData({ rows: [], columns: [], counts: { all: 0, low: 0, medium: 0, high: 0 } });
    } finally {
      setLoading(false);
    }
  }, [filter, maskPII]);

  useEffect(() => {
    fetchSnapshot();
  }, [fetchSnapshot]);

  const getMemberIdFromRow = (row) => {
    for (const col of MEMBER_ID_COLS) {
      if (row[col] != null && String(row[col]).trim() && String(row[col]).trim() !== '••••••') {
        return String(row[col]).trim();
      }
    }
    return null;
  };

  const performSend = useCallback(async (payload) => {
    if (!payload) return;
    setSending(true);
    setSendStatus(null);
    try {
      const res = await axios.post(`${API_BASE}/send-notification`, payload);
      const d = res.data;
      if (d.success) {
        setSendStatus({ type: 'success', message: `Notification ${d.status} via ${d.channel || 'channel'}.` });
      } else {
        const errMsg = d.pushover_error || d.error || d.message || 'Send failed';
        setSendStatus({ type: 'error', message: errMsg });
      }
    } catch (err) {
      const msg = err.response?.data?.error || err.message || 'Failed to send notification';
      setSendStatus({ type: 'error', message: msg });
    } finally {
      setSending(false);
    }
  }, []);

  useEffect(() => {
    if (!previewOpen || !previewPayload) return;
    const id = setInterval(() => {
      setCountdown((c) => {
        if (c <= 1) {
          performSend(previewPayload);
          setPreviewOpen(false);
          setPreviewPayload(null);
          setPreviewMessage('');
          return previewCountdownSec;
        }
        return c - 1;
      });
    }, 1000);
    countdownRef.current = id;
    return () => {
      clearInterval(id);
      countdownRef.current = null;
    };
  }, [previewOpen, previewPayload, performSend, previewCountdownSec]);

  const handleSendNotification = useCallback(async () => {
    if (selectedRowIndex == null || selectedRowIndex < 0) return;
    setSending(true);
    setSendStatus(null);
    setPreviewOpen(false);
    try {
      const row = data.rows[selectedRowIndex];
      const memberId = getMemberIdFromRow(row);
      const payload = memberId
        ? { member_id: memberId }
        : { row_index: selectedRowIndex, filter, filter_by: 'adherence' };
      const res = await axios.post(`${API_BASE}/notification-preview`, payload);
      const d = res.data;
      if (!d.success) {
        setSendStatus({ type: 'error', message: d.error || 'Could not load preview' });
        return;
      }
      setPreviewMessage(d.message || '');
      setPreviewPayload(payload);
      setCountdown(previewCountdownSec);
      setPreviewOpen(true);
    } catch (err) {
      const msg = err.response?.data?.error || err.message || 'Failed to load preview';
      setSendStatus({ type: 'error', message: msg });
    } finally {
      setSending(false);
    }
  }, [selectedRowIndex, data.rows, filter]);

  const handlePreviewSendNow = useCallback(() => {
    if (countdownRef.current) clearInterval(countdownRef.current);
    countdownRef.current = null;
    if (previewPayload) {
      performSend({ ...previewPayload, message: previewMessage.trim() || undefined });
    }
    setPreviewOpen(false);
    setPreviewPayload(null);
    setPreviewMessage('');
    setCountdown(previewCountdownSec);
  }, [previewPayload, previewMessage, performSend, previewCountdownSec]);

  const handlePreviewCancel = useCallback(() => {
    if (countdownRef.current) clearInterval(countdownRef.current);
    countdownRef.current = null;
    setPreviewOpen(false);
    setPreviewPayload(null);
    setPreviewMessage('');
    setCountdown(previewCountdownSec);
  }, [previewCountdownSec]);

  const handleBulkSendOpen = (level) => {
    setBulkLevel(level);
    setBulkMessage('');
    setBulkResult(null);
    setBulkConfirmOpen(true);
  };

  const handleBulkSendConfirm = useCallback(async () => {
    if (!bulkLevel) return;
    setBulkSending(true);
    setBulkResult(null);
    try {
      const res = await axios.post(`${API_BASE}/send-bulk-notification`, {
        adherence_level: bulkLevel,
        message: bulkMessage.trim() || undefined,
      });
      const d = res.data;
      setBulkResult({ sent: d.sent ?? 0, failed: d.failed ?? 0, total: d.total ?? 0, errors: d.errors ?? [] });
      if (d.sent > 0) fetchSnapshot();
    } catch (err) {
      setBulkResult({ sent: 0, failed: 0, total: 0, errors: [err.response?.data?.error || err.message || 'Request failed'] });
    } finally {
      setBulkSending(false);
    }
  }, [bulkLevel, bulkMessage, fetchSnapshot]);

  const handleBulkSendClose = useCallback(() => {
    setBulkConfirmOpen(false);
    setBulkLevel(null);
    setBulkMessage('');
    setBulkResult(null);
  }, []);

  const displayColumns = getDisplayColumns(data.columns);

  const columnDistinctValues = React.useMemo(() => {
    const out = {};
    displayColumns.forEach((col) => {
      out[col] = getColumnDistinctValues(data.rows, col);
    });
    return out;
  }, [data.rows, displayColumns]);

  const visibleRows = React.useMemo(() => {
    const withIndex = data.rows.map((row, idx) => ({ row, originalIndex: idx }));
    let result = withIndex;
    displayColumns.forEach((col) => {
      const filterSet = columnFilters[col];
      if (filterSet == null) return;
      if (filterSet.size === 0) {
        result = [];
        return;
      }
      result = result.filter(({ row }) => {
        const display = getDisplayValue(row[col]);
        return filterSet.has(display);
      });
    });
    return result;
  }, [data.rows, displayColumns, columnFilters]);

  const toggleColumnFilter = useCallback((col, value) => {
    const allValues = columnDistinctValues[col] || [];
    setColumnFilters((prev) => {
      const current = prev[col];
      const next = new Set(current === null ? allValues : current);
      if (next.has(value)) next.delete(value);
      else next.add(value);
      const nextState = { ...prev };
      nextState[col] = next.size === 0 ? null : next;
      return nextState;
    });
  }, [columnDistinctValues]);

  const setColumnFilterSelectAll = useCallback((col, checked) => {
    setColumnFilters((prev) => {
      const next = { ...prev };
      next[col] = checked ? null : new Set();
      return next;
    });
  }, []);

  const clearColumnFilter = useCallback((col) => {
    setColumnFilters((prev) => {
      const next = { ...prev };
      next[col] = null;
      return next;
    });
  }, []);

  const isColumnValueChecked = (col, value) => {
    const filterSet = columnFilters[col];
    return filterSet === null || (filterSet && filterSet.has(value));
  };

  const isColumnSelectAllChecked = (col) => {
    const filterSet = columnFilters[col];
    const distinct = columnDistinctValues[col] || [];
    return filterSet === null || (filterSet && filterSet.size === distinct.length);
  };

  const hasActiveColumnFilter = (col) => columnFilters[col] != null;

  const hasSelection = selectedRowIndex != null && selectedRowIndex >= 0 && selectedRowIndex < data.rows.length;
  const filters = [
    { key: 'all', label: 'All', count: data.counts.all },
    { key: 'low', label: 'Low', count: data.counts.low },
    { key: 'medium', label: 'Medium', count: data.counts.medium },
    { key: 'high', label: 'High', count: data.counts.high },
  ];

  return (
    <div className="data-snapshot card chart-3d">
      <div className="data-snapshot-header">
        <h3 className="card-title">📋 Data Snapshot (Excel)</h3>
        <div className="data-snapshot-controls">
          <div className="snapshot-filter-group">
            <span className="filter-label">Adherence:</span>
            {filters.map((f) => (
              <button
                key={f.key}
                type="button"
                className={`snapshot-filter-btn ${filter === f.key ? 'active' : ''} ${f.key !== 'all' ? `filter-${f.key}` : ''}`}
                onClick={() => setFilter(f.key)}
              >
                {f.label}
                <span className="filter-count">({f.count})</span>
              </button>
            ))}
          </div>
          <div className="snapshot-actions">
            <button
              type="button"
              className="send-notification-btn"
              disabled={!hasSelection || sending}
              onClick={handleSendNotification}
              title={hasSelection ? 'Send notification to selected patient' : 'Select a row first'}
            >
              {sending ? 'Sending…' : '📤 Send notification'}
            </button>
            <span className="bulk-send-label">Bulk:</span>
            <button
              type="button"
              className="bulk-send-btn bulk-send-low"
              disabled={data.counts.low === 0 || sending}
              onClick={() => handleBulkSendOpen('low')}
              title="Send notification to all low-adherence patients"
            >
              Send to Low ({data.counts.low})
            </button>
            <button
              type="button"
              className="bulk-send-btn bulk-send-medium"
              disabled={data.counts.medium === 0 || sending}
              onClick={() => handleBulkSendOpen('medium')}
              title="Send notification to all medium-adherence patients"
            >
              Send to Medium ({data.counts.medium})
            </button>
            <button
              type="button"
              className="bulk-send-btn bulk-send-high"
              disabled={data.counts.high === 0 || sending}
              onClick={() => handleBulkSendOpen('high')}
              title="Send notification to all high-adherence patients"
            >
              Send to High ({data.counts.high})
            </button>
          </div>
          <div className="pii-toggle-wrap">
            <button
              type="button"
              className={`pii-toggle-btn ${!maskPII ? 'visible' : ''}`}
              onClick={() => (maskPII ? setPiiConfirmOpen(true) : setMaskPII(true))}
              title={maskPII ? 'Click to show PII data' : 'Click to hide PII data'}
            >
              {maskPII ? (
                <>
                  <span className="pii-icon">👁‍🗨</span>
                  Show PII
                </>
              ) : (
                <>
                  <span className="pii-icon">🔒</span>
                  Hide PII
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      <div className="data-snapshot-body">
        {(error || sendStatus) && (
          <div className="data-snapshot-messages">
            {error && <div className="data-snapshot-error">{error}</div>}
            {sendStatus && (
              <div className={`data-snapshot-send-status ${sendStatus.type === 'success' ? 'success' : 'error'}`}>
                {sendStatus.message}
              </div>
            )}
          </div>
        )}

        {loading ? (
          <div className="data-snapshot-loading">Loading snapshot...</div>
        ) : data.rows.length === 0 ? (
          <div className="data-snapshot-empty">No patient data.</div>
        ) : (
          <>
            <div className="data-snapshot-table-wrap">
              <table className="data-snapshot-table">
                <thead>
                  <tr>
                    {displayColumns.map((col) => {
                      const distinctValues = columnDistinctValues[col] || [];
                      const hasFilter = hasActiveColumnFilter(col);
                      return (
                        <th key={col} className="th-column-filter-header">
                          <span className="th-column-filter-label">
                            {col}
                            <span
                              className={`th-column-filter-icon ${hasFilter ? 'is-active' : ''}`}
                              title={hasFilter ? 'Filter active (hover to change)' : 'Filter by value (hover to open)'}
                            >
                              ▾
                            </span>
                          </span>
                          <div className="th-column-filter-wrap">
                            <div className="th-column-filter-dropdown">
                              <div className="th-column-filter-top">
                                <label className="th-column-filter-select-all">
                                  <input
                                    type="checkbox"
                                    checked={isColumnSelectAllChecked(col)}
                                    onChange={(e) => setColumnFilterSelectAll(col, e.target.checked)}
                                  />
                                  Select All
                                </label>
                                <button
                                  type="button"
                                  className="th-column-filter-clear-btn"
                                  disabled={!hasFilter}
                                  onClick={() => clearColumnFilter(col)}
                                  title="Clear filter"
                                >
                                  ✕ Clear
                                </button>
                              </div>
                              <div className="th-column-filter-options">
                                {distinctValues.map((val) => (
                                  <label key={String(val)} className="th-column-filter-option">
                                    <input
                                      type="checkbox"
                                      checked={isColumnValueChecked(col, val)}
                                      onChange={() => toggleColumnFilter(col, val)}
                                    />
                                    {String(val)}
                                  </label>
                                ))}
                              </div>
                            </div>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody>
                  {visibleRows.length === 0 ? (
                    <tr>
                      <td colSpan={displayColumns.length} className="data-snapshot-empty-cell">
                        No rows match the column filters.
                      </td>
                    </tr>
                  ) : (
                    visibleRows.map(({ row, originalIndex }) => (
                      <tr
                        key={originalIndex}
                        className={selectedRowIndex === originalIndex ? 'selected' : ''}
                        onClick={() => setSelectedRowIndex(originalIndex)}
                      >
                        {displayColumns.map((col) => (
                          <td key={col}>{row[col] ?? ''}</td>
                        ))}
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
            <p className="data-snapshot-hint">Click a row to select a patient, then use &quot;Send notification&quot; to send manually.</p>
          </>
        )}
      </div>

      {previewOpen && (
        <div className="notification-preview-overlay" role="dialog" aria-modal="true" aria-labelledby="preview-title">
          <div className="notification-preview-modal">
            <h3 id="preview-title" className="notification-preview-title">Preview – sending in {countdown}s</h3>
            <div className="notification-preview-controls">
              <label className="notification-preview-label">
                Countdown: 
                <select
                  className="notification-preview-countdown-select"
                  value={previewCountdownSec}
                  onChange={(e) => {
                    const val = Number(e.target.value);
                    setPreviewCountdownSec(val);
                    setCountdown(val);
                  }}
                  aria-label="Preview countdown duration in seconds"
                >
                  {PREVIEW_COUNTDOWN_OPTIONS.map((sec) => (
                    <option key={sec} value={sec}>{sec} seconds</option>
                  ))}
                </select>
              </label>
            </div>
            <p className="notification-preview-label">Update the message below if you want, then send now or wait for countdown.</p>
            <textarea
              className="notification-preview-message-editable"
              value={previewMessage}
              onChange={(e) => setPreviewMessage(e.target.value)}
              placeholder="Notification message"
              rows={8}
              aria-label="Edit notification message"
            />
            <div className="notification-preview-actions">
              <button type="button" className="notification-preview-btn send-now" onClick={handlePreviewSendNow}>
                Send now
              </button>
              <button type="button" className="notification-preview-btn cancel" onClick={handlePreviewCancel}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {piiConfirmOpen && (
        <div className="notification-preview-overlay pii-confirm-overlay" role="dialog" aria-modal="true" aria-labelledby="pii-confirm-title">
          <div className="notification-preview-modal pii-confirm-modal">
            <h3 id="pii-confirm-title" className="notification-preview-title">Confirm</h3>
            <p className="pii-confirm-message">Are you sure you want to see PII data?</p>
            <div className="notification-preview-actions">
              <button type="button" className="notification-preview-btn send-now" onClick={() => { setMaskPII(false); setPiiConfirmOpen(false); }}>
                Yes, show PII
              </button>
              <button type="button" className="notification-preview-btn cancel" onClick={() => setPiiConfirmOpen(false)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {bulkConfirmOpen && bulkLevel && (
        <div className="notification-preview-overlay bulk-confirm-overlay" role="dialog" aria-modal="true" aria-labelledby="bulk-confirm-title">
          <div className="notification-preview-modal bulk-confirm-modal">
            <h3 id="bulk-confirm-title" className="notification-preview-title">
              Bulk send to {bulkLevel} adherence
            </h3>
            <p className="notification-preview-label">
              This will send a notification to all patients in the <strong>{bulkLevel}</strong> adherence group ({data.counts[bulkLevel]} patients). Optional custom message:
            </p>
            <textarea
              className="notification-preview-message-editable bulk-message-textarea"
              value={bulkMessage}
              onChange={(e) => setBulkMessage(e.target.value)}
              placeholder="Leave empty to use default adherence message per patient"
              rows={4}
              aria-label="Optional bulk message"
            />
            {bulkResult && (
              <div className={`data-snapshot-send-status ${bulkResult.failed > 0 ? 'error' : 'success'}`}>
                Sent: {bulkResult.sent}, Failed: {bulkResult.failed}, Total: {bulkResult.total}
                {bulkResult.errors.length > 0 && (
                  <details className="bulk-errors-details">
                    <summary>Errors</summary>
                    <ul>{bulkResult.errors.slice(0, 10).map((e, i) => <li key={i}>{e}</li>)}</ul>
                  </details>
                )}
              </div>
            )}
            <div className="notification-preview-actions">
              {!bulkResult ? (
                <>
                  <button type="button" className="notification-preview-btn send-now" onClick={handleBulkSendConfirm} disabled={bulkSending}>
                    {bulkSending ? 'Sending…' : 'Send to all'}
                  </button>
                  <button type="button" className="notification-preview-btn cancel" onClick={handleBulkSendClose} disabled={bulkSending}>
                    Cancel
                  </button>
                </>
              ) : (
                <button type="button" className="notification-preview-btn cancel" onClick={handleBulkSendClose}>
                  Close
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default DataSnapshot;
