import React from 'react';
import './AnimatedAgentRobot.css';

/**
 * Animated agent robot icon: 6-step loop
 * Start → Hand Wave → Gear Rotation → Apex → Decay → Reset
 * Replaces the static 🤖 beside Auto Notifications toggle.
 */
function AnimatedAgentRobot({ className = '' }) {
  return (
    <div className={`animated-agent-robot ${className}`} aria-hidden>
      <div className="animated-agent-robot__overheads">
        <span className="animated-agent-robot__gear" aria-hidden />
        <span className="animated-agent-robot__lightbulb" aria-hidden />
        <span className="animated-agent-robot__sparkle animated-agent-robot__sparkle--1" aria-hidden />
        <span className="animated-agent-robot__sparkle animated-agent-robot__sparkle--2" aria-hidden />
        <span className="animated-agent-robot__sparkle animated-agent-robot__sparkle--3" aria-hidden />
      </div>
      <div className="animated-agent-robot__glow" aria-hidden />
      <svg
        className="animated-agent-robot__svg"
        viewBox="-6 0 76 80"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden
        style={{ shapeRendering: 'geometricPrecision' }}
        overflow="visible"
      >
        {/* Antennae */}
        <g className="animated-agent-robot__antennae">
          <line x1="22" y1="8" x2="20" y2="2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <line x1="42" y1="8" x2="44" y2="2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <circle cx="20" cy="2" r="2" fill="currentColor" />
          <circle cx="44" cy="2" r="2" fill="currentColor" />
        </g>
        {/* Head - filled for clarity */}
        <ellipse className="animated-agent-robot__head" cx="32" cy="22" rx="18" ry="14" stroke="currentColor" strokeWidth="2.5" fill="rgba(255,255,255,0.12)" />
        {/* Face screen - solid bright */}
        <rect className="animated-agent-robot__face" x="20" y="14" width="24" height="16" rx="2" fill="currentColor" />
        {/* Eyes: one open, one winking */}
        <circle className="animated-agent-robot__eye-open" cx="26" cy="21" r="2.5" fill="var(--bg-card)" />
        <path className="animated-agent-robot__eye-wink" d="M38 19.5 Q40 21 38 22.5" stroke="var(--bg-card)" strokeWidth="2" strokeLinecap="round" fill="none" />
        {/* Smile */}
        <path d="M24 26 Q32 30 40 26" stroke="var(--bg-card)" strokeWidth="1.8" strokeLinecap="round" fill="none" />
        {/* Body - filled for clarity */}
        <ellipse className="animated-agent-robot__body" cx="32" cy="52" rx="16" ry="18" stroke="currentColor" strokeWidth="2.5" fill="rgba(255,255,255,0.1)" />
        <circle className="animated-agent-robot__core" cx="32" cy="52" r="6" stroke="currentColor" strokeWidth="2" fill="none" />
        {/* Right arm (robot's right) — from right stomach, bent at elbow, hand on right; waves — draw first */}
        <g className="animated-agent-robot__arm animated-agent-robot__arm--right">
          <path
            d="M48 50 L52 54 L56 51"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
          <path
            d="M54 48 L62 50 L60 54 L54 54 L52 51 Z"
            fill="currentColor"
            stroke="currentColor"
            strokeWidth="1"
          />
        </g>
        {/* Left arm (robot's left) — from left stomach, bent at elbow, hand on left — draw last so always on top */}
        <g className="animated-agent-robot__arm animated-agent-robot__arm--left">
          <path
            d="M16 50 L12 54 L8 51"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
          <path
            d="M4 48 L12 50 L10 54 L4 54 L6 51 Z"
            fill="currentColor"
            stroke="currentColor"
            strokeWidth="1"
          />
        </g>
      </svg>
    </div>
  );
}

export default AnimatedAgentRobot;
