import React from 'react';

function RobotLoader({
  title = 'RoboCare is fetching live insights',
  subtitle = 'Syncing patient KPIs and dashboard metrics',
}) {
  return (
    <div className="loading loading--robot" role="status" aria-live="polite">
      <div className="robot-loader" aria-hidden="true">
        <div className="robot-head">
          <div className="robot-antenna" />
          <div className="robot-face">
            <div className="robot-eye robot-eye--left" />
            <div className="robot-eye robot-eye--right" />
            <div className="robot-mouth" />
          </div>
        </div>
        <div className="robot-scan" />
      </div>

      <div className="robot-loading-title">{title}</div>
      <div className="robot-loading-sub">
        {subtitle}
        <span className="robot-dots" aria-hidden="true" />
      </div>

      <div className="robot-progress" aria-hidden="true">
        <div className="robot-progress-bar" />
      </div>
    </div>
  );
}

export default RobotLoader;

